var t=`0259-timpana`;var a=`world-0259`;var n=`MT`;var o=`southern-europe`;var s=4;var r=76;var l={en:`Timpana`,ua:`Тімпана`};var g={en:`A traditional Malta dish made with macaroni, ground beef, yellow onion, tomato passata. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Мальта. Основні інгредієнти: макарони, яловичий фарш, жовта цибуля, томатна пасата. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Cook the pasta in generously salted boiling water for about 9 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 9 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:9,i:[[`macaroni`,380,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 16 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 16 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:16,i:[[`ground-beef`,450,`g`],[`yellow-onion`,160,`g`],[`tomato-passata`,330,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`chicken-egg`,3,`pcs`],[`whole-cow-milk`,230,`ml`],[`parmigiano-reggiano`,60,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:6,i:[[`puff-pastry`,430,`g`]]},{en:`Bake in a preheated 180°C oven for about 40 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 40 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:40,i:[]}];var u={slug:t,id:a,country:`MT`,region:o,servings:4,minutes:76,title:l,text:g,steps:d};export{n as country,u as default,a as id,r as minutes,o as region,s as servings,t as slug,d as steps,g as text,l as title};